function validate([items, k]) {
  const n = items.length;
  if (n < 1 || n > 100000) return 'items needs 1 to 10^5 entries.';
  for (const item of items) {
    if (item.length !== 2) return 'Each item is [profit, category].';
    if (item[0] < 1 || item[0] > 1000000000) return 'Each profit is between 1 and 10^9.';
    if (item[1] < 1 || item[1] > n) return 'Each category is between 1 and n.';
  }
  if (k < 1 || k > n) return 'k is between 1 and n.';
  return null;
}

