function findMaximumElegance(items, k) {
  items.sort((a, b) => b[0] - a[0]);
  const seen = new Set();
  const duplicates = [];
  let total = 0;
  for (let i = 0; i < k; i++) {
    const [profit, category] = items[i];
    total += profit;
    if (seen.has(category)) {
      duplicates.push(profit);
    } else {
      seen.add(category);
    }
  }
  let best = total + seen.size * seen.size;
  for (let i = k; i < items.length; i++) {
    const [profit, category] = items[i];
    if (duplicates.length === 0) {
      break;
    }
    if (seen.has(category)) {
      continue;
    }
    total += profit - duplicates.pop();
    seen.add(category);
    best = Math.max(best, total + seen.size * seen.size);
  }
  return best;
}

