function findMaximumElegance(items, k) {
  // Score every set of exactly k indices.
  const n = items.length;
  let best = -1;
  for (let mask = 0; mask < (1 << n); mask++) {
    let chosen = 0;
    let profit = 0;
    const categories = new Set();
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        chosen++;
        profit += items[i][0];
        categories.add(items[i][1]);
      }
    }
    if (chosen === k) best = Math.max(best, profit + categories.size * categories.size);
  }
  return best;
}

