function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  // Few categories make many duplicates; many categories make swaps attractive.
  const categoryCount = 1 + Math.floor(rand() * (rand() < 0.5 ? Math.min(n, large ? 40 : 3) : n));
  const mode = rand();
  const profit = () => {
    if (large || mode < 0.2) return 1 + Math.floor(rand() * 1000000000);
    if (mode < 0.7) return 1 + Math.floor(rand() * 12);
    return 1 + Math.floor(rand() * 60);
  };
  const items = Array.from({ length: n }, () => [profit(), 1 + Math.floor(rand() * categoryCount)]);
  const k = 1 + Math.floor(rand() * n);
  return [items, k];
}
